import (
	"context"
	"errors"
	"testing"
	"time"

	"github.com/stretchr/testify/suite"

	"evalfixture/domaintest"
	"evalfixture/hasher/fakes"
	"evalfixture/repository"
	repofakes "evalfixture/repository/fakes"
	"evalfixture/service"
)

type accessServiceSuite struct {
	suite.Suite
	ctx     context.Context
	users   *repofakes.FakeUserRepository
	hasher  *fakes.FakeHasher
	service *service.AccessService
}

func TestAccessServiceSuite(t *testing.T) {
	suite.Run(t, new(accessServiceSuite))
}

func (s *accessServiceSuite) SetupTest()    { s.init() }
func (s *accessServiceSuite) SetupSubTest() { s.init() }

func (s *accessServiceSuite) init() {
	s.ctx = context.Background()
	s.users = repofakes.NewFakeUserRepository()
	s.hasher = fakes.NewFakeHasher()
	s.service = service.NewAccessService(s.users, s.hasher, time.Hour)
}

func (s *accessServiceSuite) Test_Register_ReturnsNoErrorForValidInputs() {
	err := s.service.Register(s.ctx, "new@example.com", "org-1", "password123")

	s.NoError(err)
}

func (s *accessServiceSuite) Test_Register_PropagatesSaveError() {
	s.users.SetSaveError(errors.New("storage full"))

	err := s.service.Register(s.ctx, "new@example.com", "org-1", "password123")

	s.ErrorContains(err, "storage full")
}

func (s *accessServiceSuite) Test_Register_StoresHashedPassword() {
	err := s.service.Register(s.ctx, "new@example.com", "org-1", "password123")
	s.Require().NoError(err)

	stored, err := s.users.GetByEmail(s.ctx, "new@example.com")
	s.Require().NoError(err)
	s.Equal(s.hasher.Hash("password123"), stored.PasswordHash())
}

func (s *accessServiceSuite) Test_Login_ReturnsSessionForCorrectCredentials() {
	err := s.service.Register(s.ctx, "alice@example.com", "org-1", "secret")
	s.Require().NoError(err)

	session, err := s.service.Login(s.ctx, "alice@example.com", "secret")

	s.NoError(err)
	s.Equal("alice@example.com", session.Email)
	s.True(session.ExpiresAt.After(time.Now()))
}

